from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def nm(f,p0,n=8):
    best=None
    for s in range(n):
        x0=np.array(p0,float)*(1+0.3*np.random.randn(len(p0))) if s else np.array(p0,float)
        try:
            r=least_squares(lambda p: f(p)-y, x0, max_nfev=4000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.mean(best.fun**2)/np.var(y), np.round(best.x,4)
